    adcs_vec3_t d_over_n = adcs_vec3_scale(&d, 1.0 / n);
    gb_state.mean_rad_s = adcs_vec3_add(&gb_state.mean_rad_s, &d_over_n);
    d2 = adcs_vec3_sub(&rate, &gb_state.mean_rad_s);
    gb_state.m2_rad_s2.x += d.x * d2.x;
    gb_state.m2_rad_s2.y += d.y * d2.y;
    gb_state.m2_rad_s2.z += d.z * d2.z;
}
